contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep, uint256 amt) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(dep > 0);
        require(address(this).balance >= dep);
        require(amt > dep);

        c.deposit{value: dep}(); if (__ESBMC_reverted()) return;

        uint256 balBefore = address(c).balance;
        uint256 recordedBefore = address(this).balance - 0;

        bool reverted;
        c.withdraw(amt); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted && address(c).balance == balBefore && address(this).balance == recordedBefore);
    }

    receive() external payable {}
}

