pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Wallet c;

    function setUp() public {
        c = new Wallet();
    }

    function _run(uint256 dep, uint256 amt) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep > 0);
        vm.assume(address(this).balance >= dep);
        vm.assume(amt > dep);
        try c.deposit{value: dep}() {} catch { return; }
        uint256 balBefore = address(c).balance;
        uint256 recordedBefore = address(this).balance - 0;
        bool reverted;
        try c.withdraw(amt) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(reverted && address(c).balance == balBefore && address(this).balance == recordedBefore);
    }

    function testFuzz_run(uint256 dep, uint256 amt) public {
        _run(dep, amt);
    }

    receive() external payable {}
}
